# 缓存格式版本：结构一变就 +1，旧缓存自动作废（宁可全量重扫，不可读错结构）
CACHE_VERSION = 1

# 去重目录的历史落点（**迁移期只读回退**）。新落点由 lit_config.yaml 的
# paths.catalogue 给出（raw/notes/lit-watch/state/local_lit_catalogue.json）。
#
# 🔴 2026-10-11：`raw/_park` 已解散，历史件进了归档层 ⇒ 这里随之改到归档层的新位置。
#    **必须同步改**：本常量是 `lit_catalogue.py` 读"上一版"做**缩水保护**的依据；
#    路径一迁不改，缩水保护就静默失效（外置盘没挂载时会一次把好好的目录换成小目录）。
#    读归档层是本库既有做法（`kb_lib.qc_input()` 就是"优先库根、缺失回退归档"）。
LEGACY_CATALOGUE_RELPATHS = (
    "_archive/retired/quarantine/_park-catalogue/local_lit_catalogue.json",
    "raw/local_lit_catalogue.json",          # 更早的落点（重构前）
)


def legacy_catalogue_paths():
    """去重目录的历史落点（迁移期只读回退）。返回绝对路径列表，去重保序。

    🔴 归档根**派生自配置的 `raw_dir` 的父目录**，不写死库根。
    为什么不能写死 `K.VAULT`：本函数的历史落点现在位于 `_archive/`（`raw/` 的**兄弟**目录，
    不在 `raw/` 之下），而 `_archive/` 不是配置项。若直接拼 `K.VAULT`：
      · 库根要搬家/更名时这里不会跟着动；
      · 更要紧的是**自检夹具**（用临时库根 + 临时配置）会读到**真实库**的路径而误判——
        这正是 `--selftest` 里 `历史落点派生自配置 raw_dir（不写死库根）` 那条在守着的东西。
    `raw_dir` 的父目录就是库根，故 `dirname(raw_dir)/_archive` 既恒等于真实位置，
    又天然跟随配置。
    """
    paths = lit_paths()
    raw = paths.get("raw_dir") or os.path.join(K.VAULT, "raw")
    vault_root = os.path.dirname(os.path.abspath(raw))
    out = [os.path.join(vault_root, *r.split("/")) for r in LEGACY_CATALOGUE_RELPATHS]
    return [p for i, p in enumerate(out) if p not in out[:i]]


