def lit_paths():
    """从 lit_config.yaml 取 paths 段（已解析为绝对路径）。

    🔴 这里**不再** `except Exception: return {}`。lit_config.yaml **存在但解析失败**时，
    kb_lib.load_lit_config 会主动抛 RuntimeError（其注释写着"宁可不跑，也不能拿空白名单去检索"）；
    旧版在本函数里把异常吞掉并退回内置默认值，等于把那条 fail-fast 又改回**静默兜底**：
    配置坏掉时本脚本照常跑完，把 dois.json 写到**旧落点**并打印成功，
    而 lit_discover 读的是配置里的新落点 ⇒ 去重清单看似正常、实际长期为空。
    文件**确实不存在**时 load_lit_config 自己会合并 LIT_CONFIG_DEFAULTS（这不算失败），
    所以这里不需要再兜一层。
    """
    return K.load_lit_config().get("paths") or {}


def out_path():
    """dois.json 落点（跟随配置 paths.doi_index；配置无此键才退回 kb_lib 索引目录）。"""
    return lit_paths().get("doi_index") or os.path.join(K.INDEX_DIR, "dois.json")


def cache_path():
    """增量缓存落点：与 dois.json **同目录**（同样跟随配置，不写死 wiki/.index）。

    放在派生数据目录下是本库的既定纪律：索引是**可重建**的派生数据，
    缓存丢了只损失一次全量扫描，不会丢知识。
    """
    return os.path.join(os.path.dirname(out_path()), "dois_cache.json")


def catalogue_candidates():
    """去重目录候选：**配置值优先**，其后才是历史落点（去重、保序）。

    🔴 为什么集中在这一个函数里：同一份 `local_lit_catalogue.json` 候选清单曾散在
    kb_dois.py / kb_baseline.py / lit_discover.py 三处（外加 kb_lib 的默认值），
    路径一迁移就有三个地方各自陈旧。此处是**唯一一份**候选逻辑，lit_catalogue.py
    直接 import 使用；kb_baseline.py / kb_deabs.py 待 Lead 折叠过来。
    历史落点只作为**只读回退**保留一个版本，不做写入目标。
    """
    cands = [lit_paths().get("catalogue")] + legacy_catalogue_paths()
    out = []
    for p in cands:
        if p and p not in out:
            out.append(p)
    return out


