def norm_doi(doi):
    """薄包装：统一走 kb_lib.norm_doi（含 CJK/全角截断、去 URL 前缀与尾标点）。

    🔴 本地旧实现只 rstrip(".")：source 页 frontmatter 里尾部粘连中文标点的 DOI
    （`…202411671。`）会以脏键写进 dois.json，去重时与目录里的干净 DOI 对不上。
    """
    return K.norm_doi(doi)


def norm_title(t):
    """标题规范化键：小写、只留字母数字与汉字（其余含空格一律剔除）。"""
    return re.sub(r"[^a-z0-9一-鿿]+", "", (t or "").lower())


# ---------------------------------------------------------------------------
# 增量缓存（per-page mtime+size）
# ---------------------------------------------------------------------------
def _load_cache(path, sources_dir):
    """读缓存；结构/版本/来源目录不符一律当**没有缓存**（宁可全量重扫）。"""
    try:
        with open(path, encoding="utf-8") as f:
            d = json.load(f)
    except Exception:                            # noqa: BLE001
        return {}
    if not isinstance(d, dict) or d.get("_version") != CACHE_VERSION:
        return {}
    if os.path.abspath(str(d.get("sources_dir") or "")) != os.path.abspath(sources_dir):
        return {}                                # 换了扫描目录 ⇒ 旧条目全部作废
    pages = d.get("pages")
    return pages if isinstance(pages, dict) else {}


def _save_cache(path, sources_dir, pages):
    """原子写缓存。失败只告警：缓存是派生数据，写不进去不该拖垮 DOI 导出。"""
    try:
        os.makedirs(os.path.dirname(path), exist_ok=True)
        tmp = path + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump({"_version": CACHE_VERSION,
                       "_generated_by": "tools/kb_dois.py",
                       "_note": "per-page mtime+size → DOI 的增量缓存，可随时删除重建",
                       "sources_dir": sources_dir,
                       "pages": pages}, f, ensure_ascii=False, separators=(",", ":"))
        os.replace(tmp, path)
    except OSError as e:
        print(f"[warn] 增量缓存写入失败（不影响 dois.json）：{e}", file=sys.stderr)


def _mtime_eq(a, b):
    """mtime 比较：JSON 往返后浮点可能差 1e-7 级，容差比较不会因此白扫一遍。"""
    try:
        return abs(float(a) - float(b)) < 1e-6
    except (TypeError, ValueError):
        return False


def collect(sources_dir=None, use_cache=True, force_rescan=False,
            cache_file=None, stats=None):
    """扫描 wiki/sources/，返回 (by_doi, by_title, n_scanned)。

    增量：每页缓存 `(mtime, size) → {doi,title,year,journal}`，只有变过的页才读盘+解析
    frontmatter。**结果必须与全量一致**——缓存只跳过"读"，不改变任何派生逻辑，
    且不复用已从目录里消失的页（缓存按当前 listdir 重放，删除的页自然不再计入）。

      use_cache=True,  force_rescan=False → 读缓存 + 写缓存（默认）
      use_cache=True,  force_rescan=True  → **不读**缓存、全量重扫，但仍重建缓存
                                            （`--full`：否则全量跑完下次还是全量）
      use_cache=False                     → 老行为：不读也不写（自检夹具用）

    显式传 `sources_dir`（自检夹具的临时目录）时默认**不读写缓存**，
    否则夹具的临时页会把脏条目灌进真实缓存。
    """
    src = sources_dir or os.path.join(K.WIKI, "sources")
    pages_dir_abs = os.path.abspath(src)
    by_doi, by_title = {}, {}
    n = 0
    hits = misses = 0
    if not os.path.isdir(src):
        if stats is not None:
            stats.update({"scanned": 0, "cache_hits": 0, "cache_misses": 0})
        return by_doi, by_title, 0

    cache_on = bool(use_cache) and (sources_dir is None or cache_file is not None)
    cpath = cache_file or cache_path()
    prev = _load_cache(cpath, pages_dir_abs) if (cache_on and not force_rescan) else {}
    fresh = {}

    for f in sorted(os.listdir(src)):
        if not f.endswith(".md"):
            continue
        n += 1
        fp = os.path.join(src, f)
        page = f[:-3]
        try:
            st = os.stat(fp)
            mtime, size = st.st_mtime, st.st_size
        except OSError:
            mtime, size = None, None          # 读不到 stat（权限/竞态）→ 老老实实重扫
        rec = prev.get(f) if cache_on else None
        if (rec and mtime is not None
                and _mtime_eq(rec.get("mtime"), mtime) and rec.get("size") == size):
            info = rec
            hits += 1
        else:
            misses += 1
            fm_raw, _ = K.split_frontmatter(K.read_text(fp))
            fm = K.parse_frontmatter(fm_raw)
            info = {
                "mtime": mtime,
                "size": size,
                "doi": norm_doi(fm.get("doi")),
                "title": str(fm.get("title") or "").strip() or page,
                "year": str(fm.get("year") or "").strip(),
                "journal": str(fm.get("journal") or "").strip(),
            }
        if cache_on:
            fresh[f] = info
        doi = info.get("doi") or ""
        title = info.get("title") or page
        if doi:
            by_doi[doi] = {"page": page, "title": title,
                           "year": info.get("year") or "",
                           "journal": info.get("journal") or ""}
        tk = norm_title(title) or norm_title(page)
        if tk:
            by_title[tk] = {"page": page, "doi": doi}

    if cache_on:
        _save_cache(cpath, pages_dir_abs, fresh)
    if stats is not None:
        stats.update({"scanned": n, "cache_hits": hits, "cache_misses": misses})
    return by_doi, by_title, n


# ---------------------------------------------------------------------------
# 原子写盘
# ---------------------------------------------------------------------------
def _atomic_write_json(path, data, backup=True):
    """先写 `.tmp` 再 `os.replace`；覆盖前把旧文件留一份 `.bak`。

    🔴 为什么必须原子：旧版直接 `open(path,"w")` 就地写。写到一半失败（磁盘满/被中断）
    就留下**截断的 JSON**，而 lit_discover.load_seen 读到坏 JSON **只打一条 warning**
    就当成空清单继续 ⇒ 下一次 lit-watch 会重复下载几乎所有已有文献。
    `.bak` 则是那份"上一版好清单"的回滚网（截断发生时它仍然完好）。
    """
    d = os.path.dirname(path)
    if d:
        os.makedirs(d, exist_ok=True)
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, separators=(",", ":"))
        f.flush()
        os.fsync(f.fileno())
    if backup and os.path.exists(path):
        try:
            shutil.copyfile(path, path + ".bak")
        except OSError as e:
            print(f"[warn] 备份 {path}.bak 失败：{e}", file=sys.stderr)
    os.replace(tmp, path)


def build(use_cache=True, force_rescan=False):
    """构建并写入 dois.json（增量 by default）。"""
    stats = {}
    by_doi, by_title, n = collect(use_cache=use_cache, force_rescan=force_rescan,
                                  stats=stats)
    data = {
        "_generated_by": "tools/kb_dois.py",
        "_note": ("知识库权威「已建卡文献」清单，供 lit 去重时与 "
                  "local_lit_catalogue.json 取并集。"
                  "by_doi 优先，by_title 为无 DOI 时的兜底键。"),
        "count": len(by_doi),
        "sources_scanned": n,
        "by_doi": by_doi,
        "by_title": by_title,
    }
    dest = out_path()
    _atomic_write_json(dest, data)
    # 写盘铁律：写 N 条就要能读回 N 条（解析器与读取方同一个）
    with open(dest, encoding="utf-8") as f:
        back = json.load(f)
    if len(back.get("by_doi") or {}) != len(by_doi):
        raise RuntimeError(f"写后复算不一致：写出 {len(by_doi)} 条，读回 "
                           f"{len(back.get('by_doi') or {})} 条（{dest}）")
    data["_stats"] = stats
    data["_path"] = dest
    return data


def load_catalogue_dois():
    """在所有候选路径里找**可读**的去重目录；单个候选读取失败继续试下一个。

    🔴 旧版在第一个 `except` 里直接 `return set(), "…读取失败…"`：候选首位（配置值）
    存在但坏掉时，后面的历史落点再也不看 —— 明明有一份好目录可用，却报"读取失败"，
    覆盖率检查随之显示"全部未覆盖"，把人误导去重复下载。
    """
    errs = []
    for p in catalogue_candidates():
        if not os.path.exists(p):
            continue
        try:
            with open(p, encoding="utf-8") as f:
                d = json.load(f)
        except Exception as e:                   # noqa: BLE001
            errs.append(f"{p}（读取失败：{e}）")
            continue
        dois = set()
        for x in (d.get("papers") or []):
            dx = norm_doi(x.get("doi"))          # 只归一一次
            if dx:
                dois.add(dx)
        return dois, p, errs
    return set(), None, errs


def check():
    """对比 KB 已有 DOI 与去重目录的覆盖情况。"""
    stats = {}
    by_doi, _, n = collect(stats=stats)
    kb = set(by_doi)
    cat, catp, errs = load_catalogue_dois()
    print("=== DOI 去重覆盖检查 ===")
    print(f"  KB source 页      : {n}（缓存命中 {stats['cache_hits']}/"
          f"重扫 {stats['cache_misses']}）")
    print(f"  KB 唯一 DOI       : {len(kb)}")
    for e in errs:
        print(f"  [!] 候选目录读取失败，已跳过：{e}")
    if catp:
        print(f"  去重目录          : {catp}")
        print(f"  目录内 DOI        : {len(cat)}")
    else:
        print("  去重目录          : 未找到")
    inter = kb & cat
    miss = kb - cat
    print(f"  已覆盖            : {len(inter)}")
    print(f"  **未覆盖（会重复下载/建卡）: {len(miss)}**")
    op = out_path()
    if os.path.exists(op):
        with open(op, encoding="utf-8") as f:
            idx = json.load(f)
        idx_dois = set(idx.get("by_doi") or {})
        print(f"  {os.path.relpath(op, K.VAULT)}: {len(idx_dois)} 条 "
              f"（与 KB 集合一致: {idx_dois == kb}）")
    else:
        print(f"  {os.path.relpath(op, K.VAULT)}: 尚未生成 → 跑 python tools/kb_dois.py")
    return 0


