# 自检
# ---------------------------------------------------------------------------
def selftest():
    print("=== kb_dois --selftest ===")
    ok = True

    def chk(name, cond, extra=""):
        nonlocal ok
        print(f"  [{'ok' if cond else 'FAIL'}] {name}{(' ' + extra) if extra else ''}")
        ok = ok and cond

    cases = [
        ("https://doi.org/10.1038/S41586-020-2442-2", "10.1038/s41586-020-2442-2"),
        ("10.1002/adfm.202411671.", "10.1002/adfm.202411671"),
        ("  ", ""),
        ("10.1021/acs.jcim.3c01250", "10.1021/acs.jcim.3c01250"),
        # 🆕 尾部粘连中文标点必须清洗（否则 dois.json 里是脏键，去重对不上）
        ("10.1002/adfm.202411671。", "10.1002/adfm.202411671"),
        # 反例：非 DOI 文本不得被"归一"成垃圾（kb_lib 明确返回空串）
        ("见文献[1]所述", ""),
    ]
    for src, want in cases:
        got = norm_doi(src)
        chk(f"norm_doi({src!r})", got == want, f"-> {got!r}")

    # 标题键：**逐个断言期望值**（旧版 `for src, _ in tc` 把期望值丢了，
    # 只判"非空且无空格"——于是两条期望值里带着空格的错误值从没被发现过）
    tc = [("A Generative Model for Inorganic Materials Design",
           "agenerativemodelforinorganicmaterialsdesign"),
          ("锂金属电池的界面", "锂金属电池的界面"),
          # 反例：纯标点必须归一为空串，否则会产生一个"空标题键"把所有无题页并成一条
          ("!!! ???", "")]
    for src, want in tc:
        got = norm_title(src)
        chk(f"norm_title({src!r})", got == want, f"-> {got!r}")

    # 惰性路径解析（旧版在 import 时就把 OUT_PATH/CATALOGUE_CANDIDATES 定死了，
    # 调用方之后改配置也拿不到新落点；这条夹具正是钉死"改了配置要跟着变"）
    import tempfile
    import unittest.mock as mock

    # 🔴 自检**不得改动仓库内任何落点**：先拍照（mtime+size），退出前比对。
    #    这不是洁癖：本仓库已发生过"自检夹具的 mock 作用域写错 ⇒ 把真实产物覆盖成夹具桩"
    #    的事故（lit_catalogue 一次把 780 条目录写成 7 条），而自检照样报 PASS。
    guard = []
    for _p in [out_path(), cache_path()]:
        guard += [_p, _p + ".new", _p + ".tmp", _p + ".bak"]

    def _snap():
        out = {}
        for p in guard:
            try:
                st = os.stat(p)
                out[p] = (st.st_mtime, st.st_size)
            except OSError:
                out[p] = None
        return out

    before = _snap()
    tmpv = tempfile.mkdtemp(prefix="kb_dois_selftest_")
    try:
        fake = {"paths": {"doi_index": os.path.join(tmpv, "x", "dois.json"),
                          "catalogue": os.path.join(tmpv, "y", "cat.json"),
                          "raw_dir": os.path.join(tmpv, "raw")}}
        with mock.patch.object(K, "load_lit_config", side_effect=lambda *a, **k: fake):
            chk("out_path() 跟随配置（惰性）",
                out_path() == fake["paths"]["doi_index"], f"-> {out_path()}")
            chk("cache_path() 与 dois.json 同目录",
                os.path.dirname(cache_path()) == os.path.dirname(out_path()))
            cands = catalogue_candidates()
            chk("目录候选首位 = 配置 catalogue",
                cands[0] == fake["paths"]["catalogue"], f"-> {cands[0]}")
            chk("目录候选无重复", len(set(cands)) == len(cands), f"({len(cands)} 个)")
            chk("历史落点派生自配置 raw_dir（不写死库根）",
                all(os.path.abspath(p).startswith(os.path.abspath(tmpv))
                    for p in cands[1:]), f"-> {cands[1:]}")
        # 配置坏掉必须**抛**（旧版吞掉异常退回默认值 ⇒ 写到陈旧落点还报成功）
        try:
            with mock.patch.object(K, "load_lit_config",
                                   side_effect=RuntimeError("夹具：配置解析失败")):
                out_path()
            chk("配置解析失败必须抛出（不得静默兜底）", False)
        except RuntimeError:
            chk("配置解析失败必须抛出（不得静默兜底）", True)

        # 增量缓存：冷跑 vs 热跑必须产出**完全相同**的结果
        src = os.path.join(tmpv, "sources")
        os.makedirs(src, exist_ok=True)
        with open(os.path.join(src, "A.md"), "w", encoding="utf-8") as f:
            f.write("---\ntype: source\ndoi: 10.1/a.1\ntitle: Title A\nyear: 2020\n"
                    "journal: J\n---\n正文\n")
        with open(os.path.join(src, "B.md"), "w", encoding="utf-8") as f:
            f.write("---\ntype: source\ndoi: 10.1/b.2。\n---\n正文\n")
        with open(os.path.join(src, "C.md"), "w", encoding="utf-8") as f:
            f.write("没有 frontmatter 的页\n")
        cf = os.path.join(tmpv, "cache.json")
        s1 = {}
        cold = collect(sources_dir=src, use_cache=True, cache_file=cf, stats=s1)
        s2 = {}
        warm = collect(sources_dir=src, use_cache=True, cache_file=cf, stats=s2)
        chk("冷跑 3 页全 miss", s1["cache_misses"] == 3 and s1["cache_hits"] == 0,
            f"-> hits={s1['cache_hits']} misses={s1['cache_misses']}")
        chk("热跑 3 页全 hit", s2["cache_hits"] == 3 and s2["cache_misses"] == 0,
            f"-> hits={s2['cache_hits']} misses={s2['cache_misses']}")
        chk("热跑结果与冷跑**逐字节一致**", cold == warm)
        full = collect(sources_dir=src, use_cache=False)
        chk("--full（无缓存）结果与热跑一致", full == warm)
        # `--full` 不读缓存但仍重建缓存：否则全量跑完下一次还是全量（跑得"没效果"）
        os.remove(cf)
        s6 = {}
        fr = collect(sources_dir=src, use_cache=True, force_rescan=True,
                     cache_file=cf, stats=s6)
        s7 = {}
        collect(sources_dir=src, use_cache=True, cache_file=cf, stats=s7)
        chk("force_rescan 全量重扫但重建缓存（随后一跑全命中）",
            fr == cold and s6["cache_hits"] == 0 and s7["cache_hits"] == 3,
            f"-> {s6['cache_hits']}/{s7['cache_hits']}")
        # 改一个页 ⇒ 该页 miss、其余仍 hit（增量不是"要么全读要么全不读"）
        with open(os.path.join(src, "A.md"), "a", encoding="utf-8") as f:
            f.write("追加\n")
        s3 = {}
        collect(sources_dir=src, use_cache=True, cache_file=cf, stats=s3)
        chk("改动过的页才重扫", s3["cache_misses"] == 1 and s3["cache_hits"] == 2,
            f"-> hits={s3['cache_hits']} misses={s3['cache_misses']}")
        # 删除的页不得从缓存里复活
        os.remove(os.path.join(src, "C.md"))
        s4 = {}
        by_doi, by_title, n4 = collect(sources_dir=src, use_cache=True,
                                       cache_file=cf, stats=s4)
        chk("删除的页不复活", n4 == 2 and len(by_title) == 2, f"-> n={n4}")
        # 缓存只跳过"读"，坏缓存（结构/版本不符）必须退回全量而不是报错
        with open(cf, "w", encoding="utf-8") as f:
            f.write('{"_version": 999, "pages": {"A.md": {"mtime": 1}}}')
        s5 = {}
        again = collect(sources_dir=src, use_cache=True, cache_file=cf, stats=s5)
        chk("版本不符的缓存退回全量且结果不变",
            again == collect(sources_dir=src, use_cache=False))
    finally:
        shutil.rmtree(tmpv, ignore_errors=True)
        chk("自检未改动仓库内任何落点（夹具作用域守卫）", before == _snap())

    # 实扫当前库只为**报数**（不是断言：自检不得依赖当前 config/文件系统状态）
    stats = {}
    by_doi, by_title, n = collect(use_cache=False, stats=stats)
    print(f"  （信息）实扫 source 页 {n}，唯一 DOI {len(by_doi)}，标题键 {len(by_title)}")
    print(f"  （信息）dois.json 落点 {out_path()}")
    print(f"  （信息）目录候选 {catalogue_candidates()}")
    print("=== selftest", "PASS ===" if ok else "FAIL ===")
    return 0 if ok else 1


def main():
    ap = argparse.ArgumentParser(description="导出知识库 DOI 权威清单")
    ap.add_argument("--stats", action="store_true", help="只统计（不写盘）")
    ap.add_argument("--check", action="store_true")
    ap.add_argument("--selftest", action="store_true")
    ap.add_argument("--full", "--no-cache", dest="full", action="store_true",
                    help="全量重扫，不读 mtime 缓存（结果必须与增量一致）；顺带重建缓存")
    ap.add_argument("--since", action="store_true",
                    help="增量（**默认行为**）：只重读 mtime/size 变化的页；与 --full 同给时 --full 生效")
    args = ap.parse_args()
    if args.selftest:
        return selftest()
    if args.check:
        return check()
    stats = {}
    if args.stats:
        by_doi, by_title, n = collect(force_rescan=args.full, stats=stats)
        print(f"  source 页 {n}  唯一 DOI {len(by_doi)}  标题键 {len(by_title)}"
              f"  缓存命中 {stats['cache_hits']}/重扫 {stats['cache_misses']}")
        return 0
    d = build(force_rescan=args.full)
    st = d.get("_stats") or {}
    sz = os.path.getsize(d["_path"]) / 1024
    print(f"[ok] 已写出 {os.path.relpath(d['_path'], K.VAULT)}"
          f"（{'全量' if args.full else '增量'}：命中 {st.get('cache_hits', 0)}/"
          f"重扫 {st.get('cache_misses', 0)}）")
    print(f"     source 页 {d['sources_scanned']}  唯一 DOI {d['count']}"
          f"  标题键 {len(d['by_title'])}  ({sz:.0f} KB)")
    return 0


if __name__ == "__main__":
    try:
        sys.exit(main())
    except RuntimeError as e:
        # lit_config.yaml 坏掉 ⇒ 明确失败并给出行，绝不"带默认值继续"（见 lit_paths 注释）
        print(f"[fail] {e}", file=sys.stderr)
        print("       未写出任何文件。请先修 tools/lit_config.yaml。", file=sys.stderr)
        sys.exit(2)
